// Cloudflare Workers port of server.js. Key comes from the Worker secret QLOO_API_KEY.
// Generated by worker/build.py. Do not edit by hand.
const BASE = "https://hackathon.api.qloo.com";
let KEY = "";
const cache = new Map(); // private in-memory cache; Qloo data is never written to the repo

async function qloo(pathname, params) {
  const url = new URL(BASE + pathname);
  for (const [k, v] of Object.entries(params)) if (v !== undefined && v !== "") url.searchParams.set(k, v);
  const ck = url.toString();
  if (cache.has(ck)) return cache.get(ck);
  if (!KEY) throw Object.assign(new Error("Server has no Qloo key configured"), { status: 503 });
  const r = await fetch(url, { headers: { "X-Api-Key": KEY } });
  if (!r.ok) throw Object.assign(new Error(`Qloo ${pathname} returned ${r.status}`), { status: 502 });
  const j = await r.json();
  cache.set(ck, j);
  return j;
}

const entities = (j) => j?.results?.entities || j?.results || [];

// Step 1 (tool call): resolve a free-text favorite to a Qloo entity.
async function resolve(name, type) {
  const j = await qloo("/search", { query: name, types: `urn:entity:${type}`, take: 1 });
  const e = entities(j)[0];
  return e ? { id: e.entity_id, name: e.name, type } : null;
}

// Step 2 (tool call): per-person recommendations seeded by their resolved favorites.
async function recommend(ids, goal, city) {
  const j = await qloo("/v2/insights", {
    "filter.type": `urn:entity:${goal}`,
    "signal.interests.entities": ids.join(","),
    "filter.location.query": city,
    take: 50,
  });
  return entities(j).map((e) => ({
    id: e.entity_id, name: e.name,
    affinity: e.query?.affinity ?? 0,
    blurb: e.properties?.short_description || e.properties?.description || "",
    address: e.properties?.address || "",
    image: e.properties?.image?.url || e.properties?.images?.[0]?.url || "",
  }));
}

// Step 3: maximin consensus. A pick is only as good as the least-happy person's affinity for it.
function consensus(perPerson, labels) {
  const table = new Map();
  perPerson.forEach((list, pi) => list.forEach((e) => {
    if (!table.has(e.id)) table.set(e.id, { ...e, scores: new Array(perPerson.length).fill(0) });
    table.get(e.id).scores[pi] = e.affinity;
  }));
  return [...table.values()].map((c) => {
    const min = Math.min(...c.scores), avg = c.scores.reduce((a, b) => a + b, 0) / c.scores.length;
    const lowest = labels[c.scores.indexOf(min)];
    return { id: c.id, name: c.name, blurb: c.blurb, address: c.address, image: c.image,
      min, avg, scores: c.scores, lovedBy: c.scores.filter((s) => s > 0).length,
      compromise: min === 0 ? `${lowest}'s favorites don't point here, so this is a stretch for them.` : `Least-matched: ${lowest} (${Math.round(min * 100)}% affinity).` };
  }).sort((a, b) => b.min - a.min || b.avg - a.avg).slice(0, 8);
}

async function plan(body) {
  const goal = ["place", "movie", "artist", "tv_show", "destination", "podcast", "book"].includes(body.goal) ? body.goal : "place";
  const people = (body.people || []).slice(0, 6);
  if (people.length < 2) throw Object.assign(new Error("Add at least 2 people"), { status: 400 });
  const city = body.city ? String(body.city).slice(0, 60) : "";
  const resolved = [], perPerson = [];
  for (const [i, p] of people.entries()) {
    const ents = [];
    for (const f of (p.favorites || []).slice(0, 6)) {
      const r = await resolve(String(f.name).slice(0, 80), f.type || "artist");
      if (r) ents.push(r);
    }
    const label = String(p.label || `Person ${i + 1}`).slice(0, 30);
    resolved.push({ label, entities: ents });
    perPerson.push(ents.length ? await recommend(ents.map((e) => e.id), goal, city) : []);
  }
  return {
    goal, city, resolved,
    method: "Each person's favorites are resolved to Qloo entities, Qloo returns per-person affinities, and picks are ranked maximin (least-happy person first).",
    picks: consensus(perPerson, resolved.map((r) => r.label)),
    note: "Qloo results are aggregate cultural affinities, not facts about any individual. Only entity names are sent to Qloo.",
  };
}

const HTML = "<!doctype html><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\">\n<title>Taste Table - group taste consensus with Qloo</title>\n<style>body{font:16px system-ui;max-width:760px;margin:2rem auto;padding:0 1rem;color:#1b1b1f}input,select,button{font:inherit;padding:.5rem;margin:.2rem 0}button{background:#3b2fd0;color:#fff;border:0;border-radius:6px;padding:.6rem 1rem;cursor:pointer}.p{border:1px solid #ddd;border-radius:8px;padding:.8rem;margin:.6rem 0}.bar{height:8px;background:#e6e6f5;border-radius:4px}.bar i{display:block;height:8px;background:#3b2fd0;border-radius:4px}small{color:#666}img{max-width:90px;float:right;border-radius:6px;margin-left:8px}</style>\n<h1>Taste Table</h1>\n<p>Everyone lists a few favorite artists. Qloo's taste graph finds places, films or music the <b>whole group</b> will like, ranked so the least-happy person is looked after first.</p>\n<label>Find: <select id=\"goal\"><option value=\"movie\">Movies</option><option value=\"place\">Places</option><option value=\"artist\">Music artists</option><option value=\"tv_show\">TV shows</option><option value=\"destination\">Destinations</option></select></label>\n<label>City (for places, optional): <input id=\"city\" placeholder=\"e.g. Kochi\"></label>\n<div id=\"people\"></div><button onclick=\"addP()\">+ Add person</button> <button onclick=\"go()\">Find consensus</button>\n<div id=\"out\"></div><p><small>Only favorite names are sent to Qloo. Results are aggregate affinities, not facts about any person.</small></p>\n<script>\nconst ex=[[\"Alex\",\"Coldplay, Radiohead, Norah Jones\"],[\"Sam\",\"Taylor Swift, Billie Eilish, Coldplay\"],[\"Riya\",\"Arijit Singh, A. R. Rahman, Coldplay\"]];\nconst esc=s=>String(s||\"\").replace(/[&<>\"]/g,c=>({\"&\":\"&amp;\",\"<\":\"&lt;\",\">\":\"&gt;\",'\"':\"&quot;\"}[c]));\nfunction addP(l=\"\",f=\"\"){const d=document.createElement(\"div\");d.className=\"p\";d.innerHTML=`<input class=\"l\" placeholder=\"Name/label\" value=\"${esc(l)}\"><br><input class=\"f\" style=\"width:95%\" placeholder=\"Favorite artists, comma separated\" value=\"${esc(f)}\">`;people.appendChild(d)}\nex.forEach(e=>addP(...e));\nasync function go(){out.textContent=\"Asking Qloo...\";const ps=[...document.querySelectorAll(\".p\")].map(d=>({label:d.querySelector(\".l\").value,favorites:d.querySelector(\".f\").value.split(\",\").map(s=>s.trim()).filter(Boolean).map(name=>({name,type:\"artist\"}))}));\nconst r=await fetch(\"/api/plan\",{method:\"POST\",body:JSON.stringify({goal:goal.value,city:city.value,people:ps})});const j=await r.json();if(!r.ok){out.textContent=j.error;return}\nout.innerHTML=\"<h2>Group picks</h2>\"+(j.picks.map(p=>`<div class=\"p\">${p.image?`<img src=\"${esc(p.image)}\" alt=\"\">`:\"\"}<b>${esc(p.name)}</b> <small>liked by ${p.lovedBy}/${ps.length}, least-happy score ${Math.round(p.min*100)}</small><div class=\"bar\"><i style=\"width:${p.min*100}%\"></i></div><small>${esc(p.compromise)}</small><br><small>${esc(p.blurb).slice(0,200)}</small></div>`).join(\"\")||\"No overlap found.\")+`<small>${esc(j.method)}</small>`}\n</script>\n";

export default {
  async fetch(req, env) {
    KEY = env.QLOO_API_KEY || "";
    const u = new URL(req.url);
    try {
      if (req.method === "POST" && u.pathname === "/api/plan") {
        const body = await req.text();
        if (body.length > 20000) throw Object.assign(new Error("Too large"), { status: 413 });
        return Response.json(await plan(JSON.parse(body || "{}")));
      }
      if (u.pathname === "/healthz") return new Response("ok");
      if (u.pathname === "/") return new Response(HTML, { headers: { "content-type": "text/html; charset=utf-8" } });
      return new Response("not found", { status: 404 });
    } catch (e) {
      return Response.json({ error: e.message }, { status: e.status || 500 });
    }
  },
};
